    if (!r.ok) return r
    this.log('info', 'drop.info', { dirs: r.value.filter((x) => x.kind === 'dir').length, files: r.value.filter((x) => x.kind === 'file').length, other: r.value.filter((x) => x.kind === 'other').length })
    return { ok: true, value: { items: r.value } }
  }

  /**
   * 左栏"从列表移除案件"（令 2125；第九版改调契约 1.4 的 POST /api/case/forget，令 2026-10-16 15:02 第一段第 3 条）：
   * 界面只给被移除那一项的位置；这里按服务登记找到对应的案件，请服务删掉登记——之后最近案件不再列它，案件文件夹和里面的一切都不动，
   * 以后再打开同一个文件夹仍是原来的案件。没有对应登记的位置忽略（没登记过的文件夹、已换了位置的旧位置）。
   * 删了登记，会话存储的案件根名单随之刷新。日志只记结果，不记路径。
   * @param request - { root }：左栏被移除那一项的文件夹。
   * @returns forgotten：这次有没有请服务删掉登记；case_id：删掉的那个案件（没有为 null）。
   */
  async caseForget(request: unknown): Promise<{ ok: true; value: { forgotten: boolean; case_id: string | null } } | ApiFail> {
    const root = (request as { root?: unknown } | null)?.root
    if (typeof root !== 'string' || !root) return { ok: false, error: { code: 'INVALID_ARGUMENT', message: '请求参数有误' } }
    const recent = await this.callApi(API_ROUTES.find((x) => x.method === 'caseRecent')!, {})
    if (!recent.ok) return recent
    const cases = (recent.value as { cases?: Array<{ case_id: string; root: string }> }).cases ?? []
    const known = cases.find((c) => sameFolder(c.root, root, this.desk.realpath))
    if (!known) { this.log('info', 'case.forget', { forgotten: false }); return { ok: true, value: { forgotten: false, case_id: null } } }
    const r = await this.callApi(API_ROUTES.find((x) => x.method === 'forgetCase')!, { case_id: known.case_id })
    if (!r.ok) { this.log('warn', 'case.forget', { ok: false, code: r.error.code }); return r }
    this.log('info', 'case.forget', { forgotten: true })
    await this.refreshCaseRoots()
    return { ok: true, value: { forgotten: true, case_id: known.case_id } }
  }

  /**
   * 第八版及以前本机记的"已从列表移除的案件"迁到服务（一次性，见 hidden-cases.ts）。服务起来后调一次；
   * 有没成的留到下次。迁过的案件下次读最近案件时就不在了。
   */
  async migrateHiddenCases(): Promise<{ ok: true; value: { total: number; done: number } }> {
    // 同一时刻只迁一遍：服务起来时和界面第一次读最近案件前都会调（复核 rv-A66 P3-2）
    this.migrating ??= (async () => {
      const route = API_ROUTES.find((x) => x.method === 'forgetCase')!
      const r = await migrateHidden(join(this.appData, HIDDEN_FILE), async (caseId) => (await this.callApi(route, { case_id: caseId })).ok)
      if (r.total) {
        this.log('info', 'case.forget_migrated', r)
        if (r.done) await this.refreshCaseRoots()
      }
      return { total: r.total, done: r.done }
    })().finally(() => { this.migrating = undefined })
    return { ok: true, value: await this.migrating }
  }

  private migrating: Promise<{ total: number; done: number }> | undefined

  private dailyQueue: Promise<unknown> = Promise.resolve()

  /**
   * 纯聊天的默认工作区"日常事务"（执行令 1156 第 4 条），见 daily-case.ts。几处同时问时排队，只建一次。
   * 日志只记结果，不记路径。
   */
  dailyCase(): Promise<DailyResult> {
    const run = this.dailyQueue.then(() => ensureDailyCase({
      marker: join(this.appData, 'daily-case.json'),
      userProfile: this.desk.userProfile, // 令 2043 第 3 条：默认放 <用户目录>\连越律师工作台，不放"文档"（Win11 默认同步到 OneDrive）
      configured: async () => (await this.setupState()).configured,
      getSettings: () => this.getSettings() as never,
      putSettings: (s) => this.putSettings(s),
      caseOpen: (req) => (this as unknown as { caseOpen(r: unknown): Promise<never> }).caseOpen(req),
    })).then((r) => {
      // 还没做首次配置（NOT_CONFIGURED）是正常状态，界面会隔一会儿再问：不记（令 2033：原来每隔几秒一条 warn 刷满日志）
      if (!r.ok && r.error.code === 'NOT_CONFIGURED') return r
      if (!r.ok || r.value.created) this.log(r.ok ? 'info' : 'warn', 'daily_case.ensure', { ok: r.ok, code: r.ok ? undefined : r.error.code, created: r.ok ? true : undefined })
      return r
    })
    this.dailyQueue = run.catch(() => undefined)
    return run
  }

  /**
   * 输入区写任务单（POST /api/task）明确失败时记上、写成时去掉（T14 第二次实跑派修 2）；记着的会话 Agent 插件整轮拒绝。
   * @param request - { session_id, hold }。
   */
  async sheetHold(request: unknown): Promise<{ ok: true; value: { held: boolean } }> {
